class NubraPortfolio(InitNubraSdk):
    """
    Fetches real-time, trading data from Nubra.
    """

    def __init__(self, client: InitNubraSdk):
        """
        Initializes the Trading Data instance using the provided Nubra SDK client.

        Args:
            client (InitNubraSdk): An authenticated instance of InitNubraSdk.
        """
        self.api_base_url = client.API_BASE_URL
        self.db_path= client.db_path
        self.totp_login = client.totp_login
        self.token_data = client.token_data
        self.db_path = client.db_path
        self.env_path_login = client.env_path_login
        self.client = BaseHttpClient(self)

    def _url(self, path):
        """
        Constructs the full API URL for a given endpoint path.

        Args:
            path (str): Relative API path.

        Returns:
            str: Full API URL.
        """
        return f"{self.api_base_url}/{path}"
    

    def positions(self, version = None):
        """
        Fetches the current portfolio positions for the logged-in user.

        It returns a structured response containing current stock, futures, options,
        and closed positions, along with profit and loss (PnL) statistics.

        Returns:
            PortfolioMessage: A Pydantic model containing a message and a detailed portfolio breakdown,
            including realized/unrealized PnL and categorized positions (stocks, futures, options, closed).

        Raises:
            NubraValidationError: If the response fails to validate against the expected data schema.
        """

        try:
            response= self.client.request("get", self._url("sentinel/portfolio/positions"))
            if response.json() is None:
                return []
            
            return PortfolioMessageV3(**response.json())
                
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())
        
    def holdings(self):
        """
        Fetches the current equity holdings for the logged-in user.

        It includes per-asset information such as quantity, average price, pledged quantity, current value, PnL, and 
        margin benefit.

        Returns:
            HoldingsMessage: A Pydantic model containing a message and a detailed portfolio with
            holding statistics (`HoldingStats`) and a list of current equity holdings (`Holding`).

        Raises:
            NubraValidationError: If the response data fails validation against the `HoldingsMessage` schema.
        """
        try:
            response= self.client.request("get", self._url("sentinel/portfolio/holdings"))
            if response.json() is None:
                return []
            
            return HoldingsMessageV3(**response.json())

        except ValidationError as ve:
            raise NubraValidationError(ve.errors())
        
    def funds(self):
        """
        Retrieves the user's funds and margin details from the portfolio.

        Returns a structured response containing a detailed breakdown of available funds, 
        collateral, pay-in/pay-out amounts, margin usage, and MTM (Mark to Market) values.

        Returns:
            PFMMessage: A Pydantic model containing a `message` string and a detailed `PFMStruct` 
            object that includes all user funds and margin information.

        Raises:
            NubraValidationError: If the response data does not conform to the expected schema 
            defined by the `PFMMessage` Pydantic model.
        """
        try:
            response= self.client.request("get",self._url("sentinel/portfolio/user_funds_and_margin"))
            if response.json() is None:
                return []
            
            return PFMMessageV3(**response.json())

        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

    def _build_toggle_payload(self, legs: Union[List[dict], dict]) -> dict:
        """
        Validate the caller-supplied toggle legs and return the JSON payload for the target API.

        ``legs`` is a single item or a list of items (dicts or model instances):

        - Sentinel + V3 trading API: items are ``SentinelDeliveryToggleLeg``-shaped
          (``refId``, ``orderQty``, ``orderDeliveryType``, ``orderSide``,
          ``targetDeliveryType``); wrapped into ``{"legs": [...]}``.
        - Sentinel + non-V3 trading API: items are ``DeliveryToggleOrder``-shaped
          (``ref_id``, ``order_side``, ``order_qty``, ``order_delivery_type``);
          translated to the new ``{"legs": [...]}`` payload.
        - Non-sentinel: items are ``DeliveryToggleOrder``-shaped; wrapped into
          ``{"orders": [...]}``.
        """
        if isinstance(legs, dict):
            legs = [legs]
        try:
            validated = SentinelDeliveryTypeToggleRequest(legs=legs)
            return validated.model_dump(by_alias=True)
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

    def toggle_delivery_margin_required(self, legs: Union[List[dict], dict]):
        """
        Preview the margin/funds required to toggle one or more positions between
        Intraday (IDAY) and Delivery (CNC).

        Args:
            legs: A single leg or a list of legs to convert.

                - Sentinel + V3 users send ``SentinelDeliveryToggleLeg`` items
                  (``refId``, ``orderQty``, ``orderDeliveryType``, ``orderSide``,
                  ``targetDeliveryType``).
                - Sentinel + non-V3 and non-sentinel users send ``DeliveryToggleOrder``
                  items (``ref_id``, ``order_side``, ``order_qty``,
                  ``order_delivery_type``).

        Returns:
            SentinelMarginInfo: For sentinel-enabled users (``totalMargin``, ``brokerage``,
                ``totalFunds``).
            MarginResponse: For non-sentinel users (``total_margin``, ``message``, …).

        Raises:
            NubraValidationError: If the legs or the response fail validation.

        Example:
            >>> # non-sentinel / non-V3 sentinel (old leg)
            >>> portfolio.toggle_delivery_margin_required(
            ...     {"ref_id": 123456, "order_side": "BUY",
            ...      "order_qty": 50, "order_delivery_type": "IDAY"}
            ... )
            >>> # V3 sentinel (new leg)
            >>> portfolio.toggle_delivery_margin_required([
            ...     {"refId": 123456, "orderQty": 50, "orderDeliveryType": "IDAY",
            ...      "orderSide": "BUY", "targetDeliveryType": "CNC"}
            ... ])
        """
        payload = self._build_toggle_payload(legs)
        try:
            response = self.client.request("post", self._url("sentinel/portfolio/toggle_delivery_margin_required"), json=payload)
            return SentinelMarginInfo(**response.json())
        
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

    def toggle_delivery_type(self, legs: Union[List[dict], dict]):
        """
        Toggle one or more positions between Intraday (IDAY) and Delivery (CNC).

        For sentinel-enabled users this is only honoured while the market is open
        (server-side ``TradingOnMiddleware``).

        Args:
            legs: A single leg or a list of legs to convert (see
                :meth:`toggle_delivery_margin_required` for the accepted item shapes).

        Returns:
            PortfolioMessageV3: For sentinel-enabled users (refreshed portfolio).
            Portfolio: For non-sentinel users (legacy V1 portfolio shape).

        Raises:
            NubraValidationError: If the legs or the response fail validation.
        """
        payload = self._build_toggle_payload(legs)
        try:
            response = self.client.request("post", self._url("sentinel/portfolio/toggle_delivery_type"), json=payload)
            return PortfolioMessageV3(**response.json())

        except ValidationError as ve:
            raise NubraValidationError(ve.errors())
        

    def strategy_tags(self):
        """
        Fetches all active strategy tags for the authenticated client.

        A tag is "active" when it has at least one active order or a live
        portfolio entry. Tags are scoped per client.

        Returns:
            StratTagsMessage: A Pydantic model with a ``stratTags`` list of the
            active strategy tag names.

        Raises:
            NubraValidationError: If the response fails to validate against the
            expected schema.
        """
        try:
            response = self.client.request("get", self._url("sentinel/strategy-portfolio"))
            # The server returns an empty body (not `null`) when there are no
            # active tags; guard on content before parsing to avoid JSONDecodeError.
            data = response.json() if response.content else None
            if data is None:
                return StratTagsMessage(stratTags=[])
            return StratTagsMessage(**data)
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

    def strategy_positions(self, tags: Optional[List[str]] = None):
        """
        Fetches positions grouped by strategy tag.

        Returns position data in the same format as portfolio positions (V2), but
        partitioned per strategy tag. Tags with no portfolio data are omitted from
        the response.

        Args:
            tags (Optional[List[str]]): Filter to specific strategy tags.
                If None or empty, returns data for all active strategy tags.

        Returns:
            StratPortfolioPositionsMessage: A Pydantic model with a list of per-tag
            position portfolios, each containing position stats and individual positions.

        Raises:
            NubraValidationError: If the response fails to validate against the expected schema.
        """
        try:
            params = [("tag", t) for t in tags] if tags else None
            response = self.client.request(
                "get", self._url("sentinel/strategy-portfolio/portfolio/positions"), params=params
            )
            # Guard on content before parsing: an empty body means no portfolios.
            data = response.json() if response.content else None
            if data is None:
                return StratPortfolioPositionsMessage(stratPortfolios=[])
            return StratPortfolioPositionsMessage(**data)
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

    def strategy_holdings(self, tags: Optional[List[str]] = None):
        """
        Fetches holdings grouped by strategy tag.

        Returns holding data in the same format as portfolio holdings, but partitioned
        per strategy tag. Tags with no portfolio data are omitted from the response.

        Args:
            tags (Optional[List[str]]): Filter to specific strategy tags.
                If None or empty, returns data for all active strategy tags.

        Returns:
            StratPortfolioHoldingsMessage: A Pydantic model with a list of per-tag
            holdings portfolios, each containing holding stats and individual holdings.

        Raises:
            NubraValidationError: If the response fails to validate against the expected schema.
        """
        try:
            params = [("tag", t) for t in tags] if tags else None
            response = self.client.request(
                "get", self._url("sentinel/strategy-portfolio/portfolio/holdings"), params=params
            )
            # Guard on content before parsing: an empty body means no portfolios.
            data = response.json() if response.content else None
            if data is None:
                return StratPortfolioHoldingsMessage(stratPortfolios=[])
            return StratPortfolioHoldingsMessage(**data)
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

    def strategy_summary(self, tags: Optional[List[str]] = None):
        """
        Fetches a lightweight PnL summary per strategy tag plus a grand total.

        Each per-tag value combines positions and holdings::

            totalPnl = positionStats.totalPnl + holdingStats.totalPnl
            todayPnl = positionStats.todayPnl + holdingStats.dayPnl

        Args:
            tags (Optional[List[str]]): Filter to specific strategy tags.
                If None or empty, summarizes all active strategy tags.

        Returns:
            StratSummaryMessage: A model with a ``stratPortfolios`` list of
            per-tag summaries and a grand ``totalPnl`` (all values in paise).

        Raises:
            NubraValidationError: If the response fails to validate against the
            expected schema.
        """
        try:
            params = [("tag", t) for t in tags] if tags else None
            response = self.client.request(
                "get", self._url("sentinel/strategy-portfolio/portfolio/summary"), params=params
            )
            data = response.json() if response.content else None
            if data is None:
                return StratSummaryMessage(stratPortfolios=[])
            return StratSummaryMessage(**data)
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

    def delete_strategy_portfolio(self, tag: str) -> None:
        """
        Permanently deletes a strategy portfolio by tag.

        Removes the tag from all intent orders for the authenticated client,
        deletes the in-memory/Redis portfolio entry, and clears all associated
        position rows. The portfolio cannot be recovered after deletion; the
        orders themselves are unaffected.

        Args:
            tag (str): The strategy tag to delete.

        Returns:
            None (HTTP 204 No Content on success).

        Raises:
            ValueError: If ``tag`` is empty.
            NubraValidationError: If the server returns an error.
        """
        if not tag:
            raise ValueError("tag must be a non-empty string")
        # Pass the tag via params so it is URL-encoded (tags may contain ".",
        # "-", spaces, or unicode).
        self.client.request(
            "delete", self._url("sentinel/strategy-portfolio"), params={"tag": tag}
        )

    def strategy_orders(self, tags: Union[List[str], str]):
        """
        Fetches intent orders grouped by strategy tag.

        Returns an ``ordersByTag`` list — one entry per requested tag — where
        each entry holds that tag's intent orders grouped by status bucket
        (``open``, ``executed``, ``cancelled``, ``rejected``, ``expired``,
        ``gtt``). Use :meth:`StratOrdersMessage.orders_for` to flatten a tag's
        orders across buckets. The entry order is not deterministic; look tags
        up by name.

        Args:
            tags (Union[List[str], str]): One or more strategy tags to fetch.
                At least one tag is required.

        Returns:
            StratOrdersMessage: A model wrapping ``ordersByTag`` with per-tag
            lookup helpers (``msg[tag]``, ``msg.get(tag)``, ``msg.orders_for(tag)``).

        Raises:
            ValueError: If ``tags`` is empty.
            NubraValidationError: If the response fails to validate against the
            expected schema.
        """
        if isinstance(tags, str):
            tags = [tags]
        # Drop empty / whitespace-only tags (the server rejects them anyway) and
        # require at least one usable tag, per the endpoint contract.
        tags = [t for t in (tags or []) if isinstance(t, str) and t.strip()]
        if not tags:
            raise ValueError("at least one non-empty tag must be provided")
        try:
            params = [("tag", t) for t in tags]
            response = self.client.request(
                "get", self._url("sentinel/strategy-portfolio/orders"), params=params
            )
            # Guard on content before parsing: an empty body means no orders.
            data = response.json() if response.content else None
            if data is None:
                return StratOrdersMessage(ordersByTag=[])
            return StratOrdersMessage(**data)
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

    def update_strategy_tags(self, orders: List[Union[StratOrderUpdate, dict]]):
        """
        Tag, untag, or move one or more orders across strategy portfolios in a
        single call.

        Each mutation is expressed per order as a delta via ``oldStratTags`` /
        ``newStratTags`` (unrelated tags on the order are preserved), or as a
        full clear via ``clearTags=True``.

        Args:
            orders (List[Union[StratOrderUpdate, dict]]): The per-order
                mutations. Each item is a :class:`StratOrderUpdate` instance or
                an equivalent dict (``orderId``, ``oldStratTags``,
                ``newStratTags``, ``clearTags``).

        Returns:
            StratOrderUpdateResponse: A model with a ``results`` list; each
            result carries the ``orderId`` and its full ``updatedStratTags``
            after the update.

        Raises:
            NubraValidationError: If the request items or the response fail
            validation.

        Example:
            >>> portfolio.update_strategy_tags([
            ...     StratOrderUpdate(orderId=100042, oldStratTags=[], newStratTags=["nifty_scalp"]),
            ...     StratOrderUpdate(orderId=100044, oldStratTags=["nifty_scalp"], newStratTags=["bank_swing"]),
            ...     StratOrderUpdate(orderId=100045, clearTags=True),
            ... ])
        """
        try:
            normalized = [
                o if isinstance(o, StratOrderUpdate) else StratOrderUpdate(**o)
                for o in orders
            ]
            payload = {
                "orders": [
                    o.model_dump(by_alias=True, exclude_none=True) for o in normalized
                ]
            }
            response = self.client.request(
                "post", self._url("sentinel/strategy-portfolio/orders"), json=payload
            )
            # Guard on content before parsing to avoid JSONDecodeError on an empty body.
            data = response.json() if response.content else None
            if data is None:
                return StratOrderUpdateResponse(results=[])
            return StratOrderUpdateResponse(**data)
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

    def set_strategy_tag_orders(self, order_ids: List[int], tag: str):
        """
        Sets the exact order membership of a single strategy tag.

        The tag is added to every order in ``order_ids`` that lacks it and
        removed from any order that currently has it but is not in the list.
        This is a "make it so" operation, unlike :meth:`update_strategy_tags`
        which applies per-order deltas.

        Args:
            order_ids (List[int]): The exact set of intent order IDs that should
                carry ``tag`` after the call.
            tag (str): The strategy tag whose membership is being set.

        Returns:
            StratOrderUpdateResponse: A model with a ``results`` list; each
            result carries the ``orderId`` and its full ``updatedStratTags``
            after the update.

        Raises:
            ValueError: If ``order_ids`` is empty or ``tag`` is empty.
            NubraValidationError: If the request or the response fail validation.

        Example:
            >>> # make orders 100042 and 100044 the only members of "nifty.scalp"
            >>> portfolio.set_strategy_tag_orders([100042, 100044], "nifty.scalp")
        """
        if not order_ids:
            raise ValueError("order_ids must be a non-empty list")
        if not tag:
            raise ValueError("tag must be a non-empty string")
        try:
            payload = SetStratTagOrdersRequest(orderIds=list(order_ids), stratTag=tag).model_dump(
                by_alias=True, exclude_none=True
            )
            response = self.client.request(
                "post", self._url("sentinel/strategy-portfolio/tag/edit-orders"), json=payload
            )
            data = response.json() if response.content else None
            if data is None:
                return StratOrderUpdateResponse(results=[])
            return StratOrderUpdateResponse(**data)
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())
